    ctx.fillStyle=col;
    ctx.fillRect(rearX+2,bodyY+2,4,bodyH-4);
    ctx.beginPath();ctx.moveTo(locoX+2,bodyY+2);ctx.lineTo(locoX+9,bodyY+2);ctx.lineTo(locoX+locoW-4,0);ctx.lineTo(locoX+9,bodyY+bodyH-2);ctx.lineTo(locoX+2,bodyY+bodyH-2);ctx.closePath();ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.14)';
    ctx.fillRect(rearX+7,bodyY+3,rearW-10,4);
    ctx.fillRect(rearX+7,bodyY+9,rearW-10,3);
    ctx.fillStyle='rgba(180,235,255,0.65)';
    ctx.fillRect(locoX+5,bodyY+3,6,4);
    ctx.fillRect(locoX+12,bodyY+2.5,3,3.5);
    ctx.fillStyle='#ffd34d';
