function drawRailTransportVisualOverlays(){
ctx.save();
for(const fac of [player,ai]){
  for(const st of (fac.trains||[])){
    if(!isRailTransportTrainVisibleForOverlay(st)||!st.shuttle)continue;
    drawStationFreightTrainShape(st.shuttle.x,st.shuttle.y,st.faction,st.shuttle.cargo||0,st.routeStatus||st.shuttle.state||'idle',getTrainPassengerCount(st),getTrainPassengerCapacity(),getStationShuttleHeading(st));
  }
  for(const unit of getRailTransportUnits(fac===player?'player':'ai')){
    if(!isRailTransportUnitVisibleForOverlay(unit))continue;
    const sx=unit.x-camera.x,sy=unit.y-camera.y;
    const waiting=isRailTransportWaitingPhase(unit);
    const reveal=isRailTransportRevealActive(unit);
    const boarding=isRailTransportBoardingActive(unit);
    if(!waiting&&!reveal&&!boarding)continue;
    const pulse=(Math.sin((tick+(unit.x||0)*0.03+(unit.y||0)*0.02)*0.28)+1)*0.5;
    ctx.save();
    if(waiting||boarding){
      ctx.strokeStyle=`rgba(109,255,178,${0.55+0.25*pulse})`;
      ctx.lineWidth=2;
      ctx.setLineDash([4,3]);
      ctx.beginPath();
      ctx.arc(sx,sy,(getRailTransportUnitRadius(unit)||12)+5+pulse*4,0,Math.PI*2);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.strokeStyle='rgba(255,213,74,0.85)';
      ctx.beginPath();
      ctx.moveTo(sx-10,sy-16);
      ctx.lineTo(sx+10,sy-16);
      ctx.stroke();
      ctx.fillStyle='rgba(6,10,16,0.90)';
      ctx.fillRect(sx-30,sy-31,60,11);
      ctx.fillStyle='#6dffb2';
      ctx.textAlign='center';
      ctx.font='bold 8px monospace';
      ctx.fillText('ČEKÁ NA VLAK',sx,sy-22);
    }
    if(reveal){
      const fx=unit.railTransportFx;
      const t=Math.max(0,Math.min(1,(fx.ticks||0)/Math.max(1,fx.maxTicks||1)));
      ctx.globalAlpha=0.45+0.35*t;
      ctx.fillStyle='rgba(109,255,178,0.18)';
      ctx.beginPath();
      ctx.arc(sx,sy,(getRailTransportUnitRadius(unit)||12)+10*(1-t)+4,0,Math.PI*2);
      ctx.fill();
      ctx.strokeStyle=`rgba(200,255,232,${0.55*t})`;
      ctx.lineWidth=2;
      ctx.beginPath();
      ctx.arc(sx,sy,(getRailTransportUnitRadius(unit)||12)+14*(1-t)+3,0,Math.PI*2);
      ctx.stroke();
      ctx.fillStyle='rgba(6,10,16,0.88)';
      ctx.fillRect(sx-24,sy-30,48,11);
      ctx.fillStyle='#d8fff0';
      ctx.textAlign='center';
      ctx.font='bold 8px monospace';
      ctx.fillText('VÝSTUP',sx,sy-21);
    }
    ctx.restore();
  }
}
ctx.restore();
}
