function threeFPEntityCenter(e){
  if(!e)return{x:0,y:0};
  if(e.type==='base')return{x:e.x+TILE,y:e.y+TILE};
  if(e.type==='tower'||e.type==='wall'||e.type==='house'||e.type==='harbor'||e.type==='apartment'||e.type==='training'||e.type==='rail'||e.type==='train'||e.type==='crane'||e.type==='silo'||e.type==='radar')return{x:e.x+TILE/2,y:e.y+TILE/2};
  return{x:e.x,y:e.y};
}
