ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#050a0e';ctx.fillRect(0,0,canvas.width,canvas.height/2);let under=0;let tx=Math.floor(fp.x/TILE),ty=Math.floor(fp.y/TILE);if(map[ty]&&map[ty][tx]!==undefined)under=map[ty][tx];ctx.fillStyle=fpFloorColor(under);ctx.fillRect(0,canvas.height/2,canvas.width,canvas.height/2);let rays=Math.max(160,Math.floor(canvas.width/2));rays=Math.min(rays,FP_MAX_RAYS);let sliceW=canvas.width/rays;let zBuf=new Float32Array(rays);for(let i=0;i<rays;i++){let rayAng=fp.ang-FP_FOV/2+(i/rays)*FP_FOV;let hit=fpCastRay(rayAng);let dist=hit.dist*Math.cos(rayAng-fp.ang);dist=Math.max(0.02,dist);zBuf[i]=dist;let lineH=Math.min(canvas.height,(canvas.height*0.95)/dist);let y1=canvas.height/2-lineH/2;let alpha=Math.max(0.18,1-dist*0.08)*(hit.side?0.78:1.0);ctx.globalAlpha=alpha;ctx.fillStyle=fpWallBaseColor(hit.code);ctx.fillRect(i*sliceW,y1,sliceW+1,lineH);}
